using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata; using Microsoft.EntityFrameworkCore.Metadata.Builders; using SmartWaste.Domain.Collection.Entities; using SmartWaste.Domain.Collection.Enums;
namespace SmartWaste.Infrastructure.Collection.Configurations;
public class CollectionAssignmentConfiguration : IEntityTypeConfiguration<CollectionAssignment> { public void Configure(EntityTypeBuilder<CollectionAssignment> b) { b.ToTable("CollectionAssignments", t=> { t.HasCheckConstraint("CK_CollectionAssignments_AssignmentNumber", "\"AssignmentNumber\" > 0"); t.HasCheckConstraint("CK_CollectionAssignments_Status", "\"Status\" IN ('Assigned', 'InProgress', 'Completed', 'PartiallyCompleted', 'Failed', 'Cancelled')"); t.HasCheckConstraint("CK_CollectionAssignments_CancellationReason", "(\"Status\" <> 'Cancelled') OR (\"CancellationReason\" IS NOT NULL AND LENGTH(TRIM(\"CancellationReason\")) BETWEEN 5 AND 500)"); }); b.HasKey(x=>x.Id); b.Property(x=>x.AssignmentNumber).HasDefaultValueSql("nextval('\"CollectionAssignmentNumberSequence\"'::regclass)").ValueGeneratedOnAdd().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw); b.HasIndex(x=>x.AssignmentNumber).IsUnique(); b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30).HasDefaultValue(CollectionAssignmentStatus.Assigned); b.Property(x=>x.CompatibilityAcknowledgement).HasMaxLength(500); b.Property(x=>x.CancellationReason).HasMaxLength(500); b.HasOne(x=>x.Driver).WithMany().HasForeignKey(x=>x.DriverId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.Vehicle).WithMany().HasForeignKey(x=>x.VehicleId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.AssignedByUser).WithMany().HasForeignKey(x=>x.AssignedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.CompatibilityAcknowledgedByUser).WithMany().HasForeignKey(x=>x.CompatibilityAcknowledgedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>x.DriverId).IsUnique().HasDatabaseName("IX_CollectionAssignments_DriverId_Unfinished").HasFilter("\"Status\" IN ('Assigned', 'InProgress')"); b.HasIndex(x=>x.VehicleId).IsUnique().HasDatabaseName("IX_CollectionAssignments_VehicleId_Unfinished").HasFilter("\"Status\" IN ('Assigned', 'InProgress')"); } }
public class CollectionAssignmentTaskClaimConfiguration : IEntityTypeConfiguration<CollectionAssignmentTaskClaim> { public void Configure(EntityTypeBuilder<CollectionAssignmentTaskClaim> b) { b.ToTable("CollectionAssignmentTaskClaims"); b.HasKey(x=>x.Id); b.HasAlternateKey(x=>new{x.Id,x.CollectionTaskId}); b.Property(x=>x.ReleaseReason).HasMaxLength(500); b.HasOne(x=>x.CollectionAssignment).WithMany(x=>x.TaskClaims).HasForeignKey(x=>x.CollectionAssignmentId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.CollectionTask).WithMany().HasForeignKey(x=>x.CollectionTaskId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.ReleasedByUser).WithMany().HasForeignKey(x=>x.ReleasedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CollectionAssignmentId,x.CollectionTaskId}).IsUnique(); b.HasIndex(x=>x.CollectionTaskId).IsUnique().HasDatabaseName("IX_CollectionAssignmentTaskClaims_TaskId_Active").HasFilter("\"IsActive\" = TRUE"); } }
public class RouteConfiguration : IEntityTypeConfiguration<Route> { public void Configure(EntityTypeBuilder<Route> b) { b.ToTable("Routes", t=>t.HasCheckConstraint("CK_Routes_RoutingMethod", "\"RoutingMethod\" IN ('ManualOrder', 'VerifiedProvider')")); b.HasKey(x=>x.Id); b.Property(x=>x.RoutingMethod).HasConversion<string>().HasMaxLength(30).HasDefaultValue(RoutingMethod.ManualOrder); b.HasOne(x=>x.CollectionAssignment).WithOne(x=>x.Route).HasForeignKey<Route>(x=>x.CollectionAssignmentId).OnDelete(DeleteBehavior.Cascade); b.HasIndex(x=>x.CollectionAssignmentId).IsUnique(); } }
public class RouteStopConfiguration : IEntityTypeConfiguration<RouteStop> { public void Configure(EntityTypeBuilder<RouteStop> b) { b.ToTable("RouteStops", t=> { t.HasCheckConstraint("CK_RouteStops_Sequence", "\"Sequence\" > 0"); t.HasCheckConstraint("CK_RouteStops_Status", "\"Status\" IN ('Pending', 'Completed', 'Failed')"); t.HasCheckConstraint("CK_RouteStops_Failure", "(\"Status\" <> 'Failed' AND \"FailureReason\" IS NULL) OR (\"Status\" = 'Failed' AND \"FailureReason\" IS NOT NULL AND LENGTH(TRIM(\"FailureReason\")) BETWEEN 5 AND 500)"); }); b.HasKey(x=>x.Id); b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(20).HasDefaultValue(RouteStopStatus.Pending); b.Property(x=>x.FailureReason).HasMaxLength(500); b.HasOne(x=>x.Route).WithMany(x=>x.Stops).HasForeignKey(x=>x.RouteId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x=>x.CollectionTask).WithMany().HasForeignKey(x=>x.CollectionTaskId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x=>x.CollectionAssignmentTaskClaim).WithMany().HasForeignKey(x=>new{x.CollectionAssignmentTaskClaimId,x.CollectionTaskId}).HasPrincipalKey(x=>new{x.Id,x.CollectionTaskId}).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.RouteId,x.Sequence}).IsUnique(); b.HasIndex(x=>x.CollectionAssignmentTaskClaimId).IsUnique(); } }
public class CollectionAssignmentStatusHistoryConfiguration : IEntityTypeConfiguration<CollectionAssignmentStatusHistory> { public void Configure(EntityTypeBuilder<CollectionAssignmentStatusHistory> b) { b.ToTable("CollectionAssignmentStatusHistories"); b.HasKey(x=>x.Id); b.Property(x=>x.FromStatus).HasConversion<string>().HasMaxLength(30); b.Property(x=>x.ToStatus).HasConversion<string>().HasMaxLength(30); b.Property(x=>x.Notes).HasMaxLength(500); b.HasOne(x=>x.CollectionAssignment).WithMany(x=>x.StatusHistory).HasForeignKey(x=>x.CollectionAssignmentId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x=>x.ChangedByUser).WithMany().HasForeignKey(x=>x.ChangedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.CollectionAssignmentId,x.ChangedAt}); } }
public class RouteStopStatusHistoryConfiguration : IEntityTypeConfiguration<RouteStopStatusHistory> { public void Configure(EntityTypeBuilder<RouteStopStatusHistory> b) { b.ToTable("RouteStopStatusHistories"); b.HasKey(x=>x.Id); b.Property(x=>x.FromStatus).HasConversion<string>().HasMaxLength(20); b.Property(x=>x.ToStatus).HasConversion<string>().HasMaxLength(20); b.Property(x=>x.Notes).HasMaxLength(500); b.HasOne(x=>x.RouteStop).WithMany(x=>x.StatusHistory).HasForeignKey(x=>x.RouteStopId).OnDelete(DeleteBehavior.Cascade); b.HasOne(x=>x.ChangedByUser).WithMany().HasForeignKey(x=>x.ChangedByUserId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x=>new{x.RouteStopId,x.ChangedAt}); } }
